/* ===== carte_dati.js =====
   Le carte ruolo dipinte, generate con nano_banana_pro dal dorso e dalla
   mascotte come riferimenti: la cornice e identica su tutte, il personaggio
   e sempre lo stesso robot, e l ombra sta SEMPRE dentro il muro. Il nome e
   la descrizione sono STAMPATI sulla carta da _scrivi_carte.py (mai testo
   raster generato dal modello). JPEG 384x576 q78, dentro il file perche la
   CSP degli artifact non lascia passare nessuna immagine esterna.

   I ruoli senza carta propria (inquisitore, campanaro, falsario, socio)
   ricadono sul gambler: crtURL ha il suo ripiego, e il gioco non deve mai
   dipendere dall arte per funzionare.
   Uso: CRT_B64.lupo -> stringa base64 senza intestazione. */
var CRT_B64 = {
    /* i quattro delle carte del 31/08, entrati nel motore il 04/09 */
    caposala: "",
    marcatore: "",
    direttore: "",
    cassiere: "",
    dorso: "",
    lupo: "",
    veggente: "",
    villico: "",
    guardiano: "",
    gemelli: "",
    dottore: "",
    medium: "",
    sciacallo: "",
    esattore: ""
};

function crtURL(chiave) {
    var d = CRT_B64[chiave] || CRT_B64.villico;
    return "data:image/jpeg;base64," + d;
}
